function Action({children,onClick,secondary=false,small=false,disabled=false,type='button',className=''}:{children:ReactNode;onClick?:()=>void;secondary?:boolean;small?:boolean;disabled?:boolean;type?:'button'|'submit';className?:string}){return <Button type={type} disabled={disabled} onClick={onClick} className={`btn ${secondary?'secondary':''} ${small?'small':''} ${className}`}>{children}</Button>}
function Picker({label,value,onChange,options}:{label:string;value:string;onChange:(s:string)=>void;options:string[]}){return <Select value={value} onValueChange={onChange}><SelectTrigger className="picker" aria-label={label}><SelectValue/></SelectTrigger><SelectContent>{options.map(o=><SelectItem key={o} value={o}>{o}</SelectItem>)}</SelectContent></Select>}
function Field({label,children}:{label:string;children:ReactNode}){return <div className="field"><Label>{label}</Label>{children}</div>}
function Status({stage}:{stage:Stage}){return <span className={'tag status '+stageInfo[stage].color}>{stageInfo[stage].label}</span>}
function Empty({title,description,children}:{title:string;description:string;children?:ReactNode}){return <div className="empty-state"><div className="empty-icon"><Compass size={30}/></div><h3>{title}</h3><p>{description}</p>{children}</div>}
function BrandMark({c,large=false}:{c:Campaign;large?:boolean}){return <span className={`brand-mark ${large?'large':''} brand-${c.brand.toLowerCase()}`}>{c.mark}</span>}
function CampaignArt({c}:{c:Campaign}){const [broken,setBroken]=useState(false);return <div className={'card-visual art-'+c.id} style={{background:c.color}}>{c.image&&!broken?<img src={c.image} alt={c.brand+' 活动主题'} loading="lazy" onError={()=>setBroken(true)}/>:<div className="type-art"><span>{c.mark}</span><small>{c.id==='notion-work'?'MAKE ROOM FOR IDEAS':c.id==='dji-pocket'?'YOUR EVERYDAY, IN MOTION':'A LITTLE FURTHER, EVERY DAY'}</small></div>}<span className="visual-brand">{c.brand}</span></div>}
