export default function Home(){
 const [guideVisit,setGuideVisit]=useState(0);
 const [previewControls,setPreviewControls]=useState(false);
 const [tutorial,setTutorial]=useState<number|null>(null);
 const tutorialRoute=useRef<Route|null>(null);
 const tutorialStarted=useRef(false);
 const tutorialBackup=useRef<{state:AppState;demo:boolean;profile:Profile}|null>(null);

 const [state,setState]=useState<AppState>(()=>initialState());const [route,setRoute]=useState<Route>({view:'onboarding'});const [drawer,setDrawer]=useState<'notifications'|'guide'|'withdraw'|'account'|null>(null);const [dialog,setDialog]=useState<'certify'|'profile'|'about'|null>(null);const [projectTab,setProjectTab]=useState('work');const [coopFilter,setCoopFilter]=useState('全部合作');const [search,setSearch]=useState('');const [platform,setPlatform]=useState('全部平台');const [region,setRegion]=useState('全部地区');const [budget,setBudget]=useState('全部预算');const [discoveryTab,setDiscoveryTab]=useState('recommended');const [saved,setSaved]=useState<string[]>([]);const [certFile,setCertFile]=useState('');const [certStatus,setCertStatus]=useState('form');const [otp,setOtp]=useState('');const [otpError,setOtpError]=useState('');const [resendCount,setResendCount]=useState(0);const [onboarding,setOnboarding]=useState<Profile>(initialState().profile);const [linkValue,setLinkValue]=useState('');const [amount,setAmount]=useState('');const [accountIndex,setAccountIndex]=useState('');const [addingAccount,setAddingAccount]=useState(false);const [newAccount,setNewAccount]=useState<Account>({method:'PayPal',region:'美国',name:'',address:''});const [agreed,setAgreed]=useState(false);const [withdrawError,setWithdrawError]=useState('');const [walletFilter,setWalletFilter]=useState('全部');
 const [editingAccount,setEditingAccount]=useState<number|null>(null);const [certUrl,setCertUrl]=useState('');const [demoMode,setDemoMode]=useState(false);const realState=useRef<AppState|null>(null);const [ready,setReady]=useState(false);
 const stateRef=useRef(state);stateRef.current=state;
 const applicationNote=state.applicationDrafts[route.id||'']||'';const setApplicationNote=(v:string)=>change(s=>({...s,applicationDrafts:{...s.applicationDrafts,[route.id||'']:v}}));const chatInput=state.messageDrafts[route.id||'']||'';const setChatInput=(v:string)=>change(s=>({...s,messageDrafts:{...s.messageDrafts,[route.id||'']:v}}));
 const change=(fn:(s:AppState)=>AppState)=>{const next=fn(stateRef.current);stateRef.current=next;setState(next)};
 const go=(view:string,id?:string)=>{if(tutorialRoute.current)tutorialRoute.current={view,id};setGuideVisit(v=>v+1);setRoute({view,id});window.location.hash=view+(id?'/'+id:'');window.scrollTo({top:0,behavior:'instant'});setDrawer(null);setDialog(null);setProjectTab('work');setLinkValue('');};
 useEffect(()=>{syncCatalog();try{const raw=localStorage.getItem('airacle-demo-v2');if(raw){const restored=JSON.parse(raw);if(restored.schema===2){setState(restored.state);setOnboarding(restored.state.profile);if(!window.location.hash)setRoute({view:restored.state.verified?'discover':'onboarding'})}}}catch{}setReady(true)},[]);
 useEffect(()=>{if(!ready||demoMode||tutorial!==null)return;try{localStorage.setItem('airacle-demo-v2',JSON.stringify({schema:2,state}))}catch{toast.error('浏览器无法保存演示数据，请避免刷新')}},[state,ready,demoMode,tutorial]);
 useEffect(()=>{const update=()=>{const [view,id]=window.location.hash.slice(1).split('/');const expected=tutorialRoute.current;if(expected&&(expected.view!==view||expected.id!==id)){history.replaceState(null,'','#'+expected.view+(expected.id?'/'+expected.id:''));setRoute(expected);return;}if(['discover','detail','cooperations','project','wallet','onboarding','verify','result'].includes(view))setRoute({view,id});};update();window.addEventListener('hashchange',update);return()=>window.removeEventListener('hashchange',update)},[]);
 useEffect(()=>{if(!resendCount)return;const t=setTimeout(()=>setResendCount(n=>n-1),1000);return()=>clearTimeout(t)},[resendCount]);
 useEffect(()=>{const context=(document as Document&{modelContext?:{registerTool:(tool:unknown,opts:unknown)=>Promise<void>|void}}).modelContext;if(!context?.registerTool)return;const controller=new AbortController();const register=(t:unknown)=>{try{void Promise.resolve(context.registerTool(t,{signal:controller.signal})).catch(()=>{})}catch{}};
 register({name:'list_creator_campaigns',description:'查看演示活动与当前合作状态。只读取数据。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({campaigns:campaigns.map(c=>({id:c.id,title:c.title,brand:c.brand,budget:c.budget,platform:c.platform})),projects:stateRef.current.projects.map(p=>({id:p.id,campaignId:p.campaignId,stage:p.stage}))})});
 register({name:'open_creator_campaign',description:'打开活动详情供用户查看，不提交报名。',inputSchema:{type:'object',properties:{campaignId:{type:'string'}},required:['campaignId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async(input:unknown)=>{const id=(input as {campaignId?:string})?.campaignId;if(!campaigns.some(c=>c.id===id))throw Error('活动不存在');go('detail',id);await new Promise(r=>setTimeout(r,0));return {opened:id,view:'detail'}}});return()=>controller.abort();},[]);
 useEffect(()=>{const refresh=(event:StorageEvent)=>{if(tutorial!==null||demoMode)return;if(event.key===ADMIN_KEY){syncCatalog();setGuideVisit(v=>v+1)}if(event.key===CREATOR_KEY){const fresh=loadCreator();change(()=>fresh);setOnboarding(fresh.profile)}};window.addEventListener('storage',refresh);return()=>window.removeEventListener('storage',refresh)},[tutorial,demoMode]);
 const current=campaigns.find(c=>c.id===route.id);const project=state.projects.find(p=>p.id===route.id);const pc=project?campaigns.find(c=>c.id===project.campaignId):null;
 const notifications=state.projects.filter(p=>!state.readNotifications.includes(notificationId(p)));const tasks=state.projects.filter(p=>needsAction(p.stage)).sort((a,b)=>nextTaskDate(a).localeCompare(nextTaskDate(b))||a.submittedAt.localeCompare(b.submittedAt));const available=balance(state);const pending=state.projects.filter(p=>p.stage==='settlement').reduce((n,p)=>n+(campaigns.find(c=>c.id===p.campaignId)?.budget||0),0);const totalEarned=state.projects.filter(p=>p.stage==='paid').reduce((n,p)=>n+(campaigns.find(c=>c.id===p.campaignId)?.budget||0),0);
 const projectPatch=(id:string,patch:Partial<Project>)=>change(s=>({...s,projects:s.projects.map(p=>p.id===id?{...p,...patch}:p)}));
 const move=(id:string,stage:Stage)=>{try{let next=advance(stateRef.current,id,stage);if(tutorial!==null&&stage==='draft')next={...next,projects:next.projects.map(p=>p.id===id?{...p,items:Object.fromEntries(deliverables(p.campaignId).map(item=>[item,'示例脚本：开场记录清晨街道，使用 Pocket 3 跟拍城市漫游；中段展示稳定画面与便携拍摄，结尾总结体验并明确标注品牌合作。'])),draft:'以自然光与街头生活为主题，制作 60 秒竖屏视频；包含产品使用场景、实际体验和品牌合作标识。'}:p)};change(()=>next);toast.success(stageInfo[stage].label)}catch(e){toast.error((e as Error).message)}};
 const openProject=(id:string)=>go('project',id);
 const startWithdraw=()=>{setEditingAccount(null);setNewAccount({method:'PayPal',region:'美国',name:'',address:''});setAmount(String(tutorial!==null?100:available));setAccountIndex(state.accounts.length?'0':'');setAgreed(tutorial!==null);setAddingAccount(!state.accounts.length);setWithdrawError('');setDrawer('withdraw')};
 function apply(c:Campaign){if(tutorial===null&&!isPublished(c)){toast.error('活动暂未开放报名');return}if(tutorial===null&&daysLeft(c)===0){toast.error('活动已截止');return}if(!state.verified||state.verifiedEmail.toLowerCase()!==state.profile.email.toLowerCase()){go('onboarding');toast('请先完成资料与邮箱验证');return}if(c.verified&&!certified(state,c.platform)){setCertUrl(state.profile.social);setCertFile('');setCertStatus('form');setDialog('certify');return}const existing=state.projects.find(p=>p.campaignId===c.id);if(existing){openProject(existing.id);return}const p={...makeProject(c.id),note:applicationNote};change(s=>({...s,projects:[p,...s.projects]}));setApplicationNote('');toast.success('报名已提交，你可以在项目中跟进进度');openProject(p.id)}
 function enterDemo(){if(!demoMode)realState.current=stateRef.current;setDemoMode(true);const sample=initialState(true);change(()=>sample);setOnboarding(sample.profile);go('discover')}
 function exitDemo(){const restored=realState.current||initialState();change(()=>restored);setOnboarding(restored.profile);setDemoMode(false);go(restored.verified?'discover':'onboarding')}
 function jump(i:number){if(!demoMode)realState.current=stateRef.current;setDemoMode(true);const sample=initialState(true);change(()=>sample);setOnboarding(sample.profile);setDrawer(null);if(i===0){change(()=>initialState());setOnboarding(initialState().profile);go('onboarding')}else if(i===1)go('verify');else if(i===2)go('discover');else if(i===3)go('detail','dji-pocket');else if(i===4){go('detail','dji-air');setCertUrl('https://www.youtube.com/@demo_creator');setCertFile('');setCertStatus('form');setDialog('certify')}else if(i===11){go('wallet');setAmount('800');setAccountIndex('');setAgreed(false);setAddingAccount(true);setEditingAccount(null);setDrawer('withdraw')}else if(i===12){const a={method:'PayPal',name:'Demo Creator',address:'demo@example.com',region:'美国'};sample.accounts=[a];const next=withdraw(sample,100,a);change(()=>next);go('result',next.withdrawals[0].id)}else{const stages:Record<number,Stage>={5:'applied',6:'confirm',7:'draft',8:'revision',9:'publish',10:'settlement'};let scenario={...sample,projects:sample.projects.filter(p=>p.campaignId!=='dji-air')};const p=makeProject('dji-air');p.note='DJI 中东航拍合作示例';scenario.projects.unshift(p);const order:Stage[]=['confirm','draft','review','publish','acceptance','settlement'];const target=stages[i];if(target!=='applied'){for(const next of order){if(next==='review'){const active=scenario.projects[0];active.items=Object.fromEntries(deliverables(p.campaignId).map(k=>[k,'演示脚本：'+k]));active.version=1;active.draft='沙漠与城市航拍故事';active.versions=[{number:1,draft:active.draft,fileName:'',items:{...active.items},at:new Date().toISOString()}]}scenario=advance(scenario,p.id,next);if(next===target)break;if(target==='revision'&&next==='review'){scenario=advance(scenario,p.id,'revision');scenario.projects[0].feedback='V1 · Mia：请补充沙漠拍摄场景的使用体验。';break}}}change(()=>scenario);openProject(p.id)}}
 function startTutorial(){
  if(tutorial!==null)return;
  tutorialBackup.current={state:stateRef.current,demo:demoMode,profile:onboarding};
  const sample=initialState();sample.profile={name:'Demo Creator',email:'creator@example.com',region:'中国',language:'中文',topic:'影像 / 旅行',social:'https://www.instagram.com/demo_creator/'};
  sample.applicationDrafts={'dji-pocket':'以城市漫游为主题拍摄 60 秒竖屏视频，展示 DJI Pocket 3 的稳定拍摄、便携性与日常创作体验，并标注品牌合作。'};
  sample.accounts=[{method:'PayPal',region:'美国',name:'Demo Creator',address:'demo@example.com'}];
  tutorialRoute.current={view:'onboarding'};setDemoMode(true);change(()=>sample);setOnboarding(sample.profile);setOtp('');setOtpError('');setSearch('');setPlatform('全部平台');setRegion('全部地区');setBudget('全部预算');setDiscoveryTab('all');setCoopFilter('全部合作');setWalletFilter('全部');setTutorial(0);go('onboarding');
  try{sessionStorage.setItem('airacle-tutorial-active','1')}catch{}
 }
 function finishTutorial(completed=false){
  const original=tutorialBackup.current;if(!original)return;tutorialRoute.current=null;
  change(()=>original.state);setOnboarding(original.profile);setDemoMode(original.demo);setTutorial(null);setOtp('');setOtpError('');setAmount('');setAgreed(false);setAddingAccount(false);setAccountIndex('');setSearch('');setPlatform('全部平台');setRegion('全部地区');setBudget('全部预算');setDiscoveryTab('recommended');setWalletFilter('全部');go(original.state.verified?'discover':'onboarding');tutorialBackup.current=null;
  try{localStorage.setItem('airacle-tutorial-v3','done');sessionStorage.removeItem('airacle-tutorial-active')}catch{}
  toast.success(completed?'教程已完成，练习数据已清除。现在开始你的合作吧！':'已跳过引导，已恢复你的工作台');
 }
 // Each page load starts the isolated tutorial, including returning visitors.
 useEffect(()=>{if(!ready||tutorialStarted.current)return;tutorialStarted.current=true;startTutorial()},[ready]);
 useEffect(()=>{
  if(tutorial===null)return;
  const p=state.projects.find(p=>p.campaignId==='dji-pocket');const w=state.withdrawals[0];
  const next=()=>setTutorial(t=>t===null?null:t+1);
  if(tutorial===0&&route.view==='verify'||tutorial===1&&state.verified&&route.view==='discover'||tutorial===2&&route.view==='detail'&&route.id==='dji-pocket'||tutorial===3&&p?.stage==='applied'||tutorial===5&&route.view==='project'||tutorial===6&&p?.stage==='draft'||tutorial===7&&p?.stage==='review'||tutorial===9&&p?.stage==='acceptance'||tutorial===11&&route.view==='wallet'||tutorial===12&&drawer==='withdraw'||tutorial===13&&route.view==='result'||tutorial===15&&route.view==='wallet'){next();return}
  if(tutorial===4&&route.view==='cooperations'&&p){change(s=>advance(s,p.id,'confirm'));next();return}
  if(tutorial===8&&p?.stage==='review'){const t=setTimeout(()=>{change(s=>{const approved=advance(s,p.id,'publish');return {...approved,projects:approved.projects.map(v=>v.id===p.id?{...v,link:'https://www.instagram.com/p/demo/'}:v)}});next()},1800);return()=>clearTimeout(t)}
  if(tutorial===10&&p?.stage==='acceptance'){const t=setTimeout(()=>{change(s=>advance(advance(s,p.id,'settlement'),p.id,'paid'));next()},2000);return()=>clearTimeout(t)}
  if(tutorial===14&&w?.status==='processing'){const t=setTimeout(()=>{change(s=>({...s,withdrawals:s.withdrawals.map(v=>v.id===w.id?{...v,status:'completed'}:v)}));next()},1800);return()=>clearTimeout(t)}
 },[tutorial,route.view,route.id,state,drawer]);
 const tutorialOverlay=()=>tutorial===null?null:<GuidedHelp key={tutorial} current={tutorialSteps[tutorial]} index={tutorial} total={tutorialSteps.length} onSkip={()=>finishTutorial()}/>;
 const renderHeader=()=>{const joining=!state.verified||['onboarding','verify'].includes(route.view);return <><div className="demo-bar"><span>{tutorial!==null?'新手教程 · 虚拟练习账户 · 不影响你的数据':demoMode?'独立场景预览 · 不影响你的工作台':'交互演示 · 数据保存在此浏览器 · 无真实交易'}</span>{demoMode&&tutorial===null&&<button onClick={exitDemo}>退出预览，返回我的工作台</button>}{tutorial===null&&<button onClick={startTutorial}>体验完整新手教程 <ChevronRight size={14}/></button>}</div><header className="topbar"><div className="header-inner"><button className="logo" onClick={()=>go('discover')} aria-label="Airacle 首页">airacle<span className="logo-dot"/></button>{!joining&&<nav aria-label="主导航">{[['discover','发现活动',Compass],['cooperations','我的合作',BriefcaseBusiness],['wallet','钱包',Wallet]].map(([v,label,Icon])=>{const Ic=Icon as typeof Compass;const active=v==='discover'?['discover','detail'].includes(route.view):v==='cooperations'?['cooperations','project'].includes(route.view):['wallet','result'].includes(route.view);return <button data-nav={v as string} key={v as string} onClick={()=>go(v as string)} className={active?'active':''}><Ic size={18}/>{label as string}{v==='cooperations'&&tasks.length>0&&<span className="nav-count">{tasks.length}</span>}</button>})}</nav>}<div className="head-right">{tutorial===null&&<a href="/admin" className="text-btn">后台管理</a>}{joining?<button className="text-btn" onClick={state.verified?()=>go('discover'):enterDemo}>{state.verified?'返回工作台':'体验示例工作台'} <ArrowUpRight size={16}/></button>:<><button className="notification-button" aria-label="消息通知" onClick={()=>setDrawer('notifications')}><Bell size={20}/>{notifications.length>0&&<i/>}</button><span className="header-divider"/><DropdownMenu><DropdownMenuTrigger asChild><button className="avatar-menu"><span className="avatar">{state.profile.name.slice(0,1).toUpperCase()}</span><span>{state.profile.name}</span><ChevronDown size={14}/></button></DropdownMenuTrigger><DropdownMenuContent align="end" className="menu-content"><DropdownMenuItem onClick={()=>{setOnboarding(state.profile);setDialog('profile')}}><Settings2 size={16}/>个人资料</DropdownMenuItem><DropdownMenuItem onClick={()=>{setCertUrl(state.profile.social);setCertFile('');setCertStatus(certified(state,socialPlatform(state.profile.social))?'done':'form');setDialog('certify')}}><ShieldCheck size={16}/>社媒认证</DropdownMenuItem><DropdownMenuSeparator/><DropdownMenuItem onClick={()=>{setOnboarding(state.profile);go('onboarding')}}><LogIn size={16}/>体验完整入驻</DropdownMenuItem><DropdownMenuItem onClick={()=>setDialog('about')}><Info size={16}/>关于演示站</DropdownMenuItem></DropdownMenuContent></DropdownMenu></>}</div></div></header></>};
 function renderCampaign(c:Campaign){return <article className="surface campaign-card" data-campaign={c.id} key={c.id}><div className="art-wrap"><CampaignArt c={c}/><button className={'save-button '+(saved.includes(c.id)?'saved':'')} aria-label={(saved.includes(c.id)?'取消收藏 ':'收藏 ')+c.title} onClick={()=>setSaved(s=>s.includes(c.id)?s.filter(x=>x!==c.id):[...s,c.id])}><Bookmark size={17} fill={saved.includes(c.id)?'currentColor':'none'}/></button></div><div className="card-body"><div className="campaign-meta"><span className="brand-mini">{c.brand}<CheckCircle2 size={12}/></span><span className="match"><Sparkles size={12}/>{recommendation(c,state.profile).join(' · ')||'探索新方向'}</span></div><h3><button onClick={()=>go('detail',c.id)}>{c.title}</button></h3><p className="muted">{c.subtitle.split(' · ')[1]}</p><div className="card-tags"><span>{c.platform}</span><span>{c.region}</span><span>{c.category}</span></div><div className="card-footer"><div><small>合作报酬</small><strong>USD {money(c.budget)}</strong></div><button className="card-arrow" aria-label={'查看活动 '+c.title} onClick={()=>go('detail',c.id)}><ArrowUpRight size={19}/></button></div><div className="card-bottom"><span><Clock3 size={12}/>{daysLeft(c)} 天后截止</span><span>{c.deliverable.split(' + ')[0]}</span></div></div></article>}
 function discover(){const availableCampaigns=campaigns.filter(c=>tutorial!==null||isPublished(c));const featured=availableCampaigns.find(c=>c.id==='dji-air')||availableCampaigns[0];const found=availableCampaigns.filter(c=>(!search||[c.brand,c.title,...c.tags].join(' ').toLowerCase().includes(search.toLowerCase()))&&(platform==='全部平台'||c.platform===platform)&&(region==='全部地区'||c.region===region)&&(budget==='全部预算'||(budget==='USD 1,000 以上'?c.budget>=1000:c.budget<1000))&&(discoveryTab!=='saved'||saved.includes(c.id))&&(discoveryTab!=='recommended'||recommendation(c,state.profile).length>=2)).sort((a,b)=>discoveryTab==='recommended'?recommendation(b,state.profile).length-recommendation(a,state.profile).length:0);const task=tasks[0],taskC=task&&campaigns.find(c=>c.id===task.campaignId);return <><div className="page-heading"><div><p className="eyebrow">CREATOR WORKSPACE</p><h1>好内容，遇见好品牌<span className="blue">.</span></h1><p className="muted">{state.profile.name}，为你的创作，找到下一次值得投入的合作。</p></div><button className="profile-chip" onClick={()=>{setOnboarding(state.profile);setDialog('profile')}}><span className="small-star"><Sparkles size={17}/></span>{state.profile.topic}<Settings2 size={14}/></button></div>{featured&&<div className="feature-grid discovery-feature"><section className="featured">{featured.image&&<img src={featured.image} alt={featured.brand+' 活动主题'}/>}<div className="featured-shade"/><div className="feature-content"><div className="tag light">精选品牌合作</div><div className="brand-word">{featured.brand}</div><h2>{featured.title}</h2><p>{featured.subtitle||featured.brief}</p><div className="feature-bottom"><span>USD <strong>{money(featured.budget)}</strong><small> / 合作报酬</small></span><button className="white-btn" onClick={()=>go('detail',featured.id)}>查看合作 <ArrowUpRight size={18}/></button></div></div></section></div>}<div className="section-heading"><h2>为你发现 <span className="count">{String(availableCampaigns.length).padStart(2,'0')}</span></h2><button className="text-btn" onClick={()=>{setOnboarding(state.profile);setDialog('profile')}}>调整匹配偏好 <Settings2 size={15}/></button></div><div className="discover-toolbar"><Tabs value={discoveryTab} onValueChange={setDiscoveryTab}><TabsList variant="line" className="line-tabs"><TabsTrigger value="recommended">为你推荐</TabsTrigger><TabsTrigger value="all">全部活动</TabsTrigger><TabsTrigger value="saved">已收藏 {saved.length||''}</TabsTrigger></TabsList></Tabs><div className="searchbox"><Search size={17}/><Input aria-label="搜索活动" placeholder="搜索品牌或活动" value={search} onChange={e=>setSearch(e.target.value)}/></div></div><div className="filter-row"><div className="filter-caption"><SlidersHorizontal size={15}/>筛选</div><Picker label="活动平台" value={platform} onChange={setPlatform} options={['全部平台','YouTube','Instagram','X']}/><Picker label="活动地区" value={region} onChange={setRegion} options={['全部地区','全球','中东','中国']}/><Picker label="合作预算" value={budget} onChange={setBudget} options={['全部预算','USD 1,000 以上','USD 1,000 以下']}/><span className="results-count">{found.length} 个活动</span>{(search||platform!=='全部平台'||region!=='全部地区'||budget!=='全部预算')&&<button className="text-btn" onClick={()=>{setSearch('');setPlatform('全部平台');setRegion('全部地区');setBudget('全部预算')}}>清除</button>}</div>{found.length?<div className="campaign-grid">{found.map(renderCampaign)}</div>:<div className="surface"><Empty title={discoveryTab==='saved'?'还没有收藏的活动':'暂时没有匹配的活动'} description="尝试放宽筛选，或发现更多品牌合作。"><Action secondary onClick={()=>{setSearch('');setPlatform('全部平台');setRegion('全部地区');setBudget('全部预算');setDiscoveryTab('all')}}>查看全部活动</Action></Empty></div>}<div className="list-end"><span/>每一份好创作，都值得被看见<span/></div></>}
 function detail(c:Campaign){const existing=state.projects.find(p=>p.campaignId===c.id);return <><button className="back-link" onClick={()=>go('discover')}><ArrowLeft size={16}/>发现活动</button><div className="detail-layout"><div><div className="detail-hero"><CampaignArt c={c}/><div className="detail-hero-label"><span className="tag light">品牌合作 · 示例活动</span><h1>{c.title}</h1><p>{c.subtitle}</p></div></div><section className="surface content-section"><div className="brand-line"><BrandMark c={c}/><div><h3>{c.brand} <CheckCircle2 size={16} className="blue"/></h3><span className="muted">品牌创作计划</span></div><span className="tag blue-tag">{recommendation(c,state.profile).join(' · ')||'探索新方向'}</span></div><h2>一次怎样的合作？</h2><p className="body-copy">{c.brief}</p><div className="brief-facts"><div><Camera size={18}/><span>交付内容<strong>{c.deliverable}</strong></span></div><div><Globe2 size={18}/><span>发布平台<strong>{c.platform}</strong></span></div><div><MapPin size={18}/><span>活动地区<strong>{c.region}</strong></span></div></div><h2>创作要求</h2><ul className="check-list">{c.requirements.map(t=><li key={t}><Check size={16}/>{t}</li>)}</ul><h2>合作时间</h2><div className="dates-line"><div><span>报名截止</span><strong>{c.deadline}</strong></div><div><span>初稿提交</span><strong>{campaignDate(c,7)}</strong></div><div><span>完成发布</span><strong>{campaignDate(c,14)}</strong></div></div><div className="soft-note"><Info size={17}/>活动是设计演示，品牌未委托本演示站招募；日期与报酬均为预设。</div></section></div><aside className="sticky-aside"><section className="surface apply-card"><p className="eyebrow">YOUR NEXT COLLABORATION</p><span className="muted">本次合作报酬</span><div className="price"><small>USD</small> {money(c.budget)}</div><div className="apply-meta"><span><CalendarDays size={16}/>还有 {daysLeft(c)} 天截止</span><span><ShieldCheck size={16}/>验收后结算</span></div><hr/><h3>{existing?'你已加入此合作':'申请这次合作'}</h3><div className="selected-profile"><span className="avatar">{state.profile.name.slice(0,1).toUpperCase()}</span><div><strong>{state.profile.name}</strong><p>{state.profile.topic}</p></div><CheckCircle2 size={18} className="blue"/></div>{c.verified&&<div className={'cert-hint '+(certified(state,c.platform)?'done':'')}><ShieldCheck size={18}/><div><strong>{certified(state,c.platform)?'社媒账号已认证':'此活动需要 '+c.platform+' 账号认证'}</strong><p>{certified(state,c.platform)?'已完成该平台账号归属核对，可直接报名。':'保留报名内容，认证通过后回来继续。'}</p></div></div>}{existing?<><Status stage={existing.stage}/><Action className="full" onClick={()=>openProject(existing.id)}>查看合作进度 <ArrowRight size={17}/></Action></>:<><Field label="合作说明（选填）"><Textarea aria-label="合作说明" value={applicationNote} onChange={e=>setApplicationNote(e.target.value)} placeholder="分享你对这次合作的创意，例如场景、选题或拍摄计划。" rows={4} maxLength={500}/></Field><Action className="full" disabled={tutorial===null&&daysLeft(c)===0} onClick={()=>apply(c)}>{c.verified&&!certified(state,c.platform)?'认证账号并继续':'提交报名'}<ArrowRight size={17}/></Action></>}<p className="tiny centered">资料仅用于本次演示，不会提交给品牌。</p></section><div className="soft-note"><MessageCircle size={18}/><div>好合作，从清晰的沟通开始。<br/>进入项目后可联系负责人。</div></div></aside></div></>}
 function collaborations(){const filtered=state.projects.filter(p=>coopFilter==='全部合作'||(coopFilter==='待我处理'?needsAction(p.stage):coopFilter==='进行中'?!['paid',...closedStages].includes(p.stage):coopFilter==='已结束'?closedStages.includes(p.stage):p.stage==='paid'));return <><div className="page-heading"><div><p className="eyebrow">MY COLLABORATIONS</p><h1>让每一次合作，有条不紊<span className="blue">.</span></h1><p className="muted">从第一次报名，到最后一笔到账。</p></div><Action secondary onClick={()=>go('discover')}>发现新活动 <ArrowUpRight size={17}/></Action></div><div className="stats-row"><div className="surface stat"><span>待我处理</span><strong>{tasks.length.toString().padStart(2,'0')}<small>项任务</small></strong></div><div className="surface stat"><span>进行中的合作</span><strong>{state.projects.filter(p=>!['paid',...closedStages].includes(p.stage)).length.toString().padStart(2,'0')}<small>个项目</small></strong></div><div className="surface stat"><span>累计合作收入</span><strong><small>USD</small>{money(totalEarned)}</strong></div></div><Tabs value={coopFilter} onValueChange={setCoopFilter}><TabsList variant="line" className="line-tabs"><TabsTrigger value="全部合作">全部合作 {state.projects.length}</TabsTrigger><TabsTrigger value="待我处理">待我处理 {tasks.length}</TabsTrigger><TabsTrigger value="进行中">进行中</TabsTrigger><TabsTrigger value="已完成">已完成</TabsTrigger><TabsTrigger value="已结束">已结束</TabsTrigger></TabsList></Tabs><div className="project-list">{filtered.map(p=>{const c=campaigns.find(c=>c.id===p.campaignId)!;return <article className="surface project-row" key={p.id}><BrandMark c={c} large/><div className="project-summary"><div className="project-meta">{c.brand}<span>·</span>{c.platform}</div><h3>{c.title}</h3><p>{c.deliverable}</p></div><div className="project-state"><Status stage={p.stage}/><p>{needsAction(p.stage)?'下一步需要你操作':p.stage==='paid'?'报酬已到账':'可随时查看进度'}</p></div><div className="project-amount"><strong>USD {money(c.budget)}</strong><span>合作报酬</span></div><Action secondary={!needsAction(p.stage)} small onClick={()=>openProject(p.id)}>{needsAction(p.stage)?'去处理':'查看项目'}<ChevronRight size={16}/></Action></article>})}{!filtered.length&&<div className="surface"><Empty title="这里还没有合作" description="去发现活动，找到与你的创作方向合拍的品牌。"><Action onClick={()=>go('discover')}>发现活动</Action></Empty></div>}</div></>}
 function projectView(p:Project,c:Campaign){const info=p.stage==='draft'?{...stageInfo.draft,next:'请在 '+campaignDate(c,7)+' 前逐项提交初稿，品牌预计 2 个工作日内反馈。'}:p.stage==='publish'&&p.returnReason?{...stageInfo.publish,label:'发布链接需修正',task:'请修正发布链接后重新提交',next:p.returnReason}:stageInfo[p.stage];const phase=['applied','confirm','negotiating'].includes(p.stage)?0:['draft','review','revision'].includes(p.stage)?1:['publish','acceptance'].includes(p.stage)?2:3;const currentDraft=p.draft;const submitDraft=()=>{if(!deliveryComplete(p)){toast.error('请为交付清单的每一项填写内容或选择文件');return}const next=advance(stateRef.current,p.id,'review');change(()=>({...next,projects:next.projects.map(pr=>pr.id===p.id?{...pr,version:pr.version+1,versions:[...pr.versions,{number:pr.version+1,draft:pr.draft,fileName:pr.fileName,items:{...pr.items},at:new Date().toISOString()}]}:pr)}));toast.success('已提交审核，版本已保存')};return <><button className="back-link" onClick={()=>go('cooperations')}><ArrowLeft size={16}/>我的合作</button><div className="project-title"><BrandMark c={c} large/><div><p className="muted">{c.brand} · {c.platform} · 合作编号 AC-{c.id.toUpperCase()}</p><h1>{c.title}</h1></div><button className="text-btn" onClick={()=>go('detail',c.id)}>活动详情 <ExternalLink size={15}/></button></div>{closedStages.includes(p.stage)?<div className="soft-note"><Info size={18}/>{stageInfo[p.stage].label} · 流程已结束，后续交付与结算未执行。</div>:<div className="project-progress">{['确认合作','内容交付','发布验收','结算到账'].map((n,i)=><div key={n} className={i<phase||p.stage==='paid'?'complete':i===phase?'current':''}><span>{i<phase||p.stage==='paid'?<Check size={15}/>:i+1}</span><strong>{n}</strong>{i<3&&<i/>}</div>)}</div>}<div className="detail-layout"><section className="surface project-main"><div className={'next-task task-'+info.color}><div>{p.stage==='publish'&&p.returnReason?<span className="tag orange">链接需修正</span>:<Status stage={p.stage}/>}<h2>{info.task}</h2><p>{info.next}</p></div><span className="task-symbol">{p.stage==='paid'?<CheckCircle2 size={37}/>:needsAction(p.stage)?<ArrowUpRight size={37}/>:<Clock3 size={37}/>}</span></div><Tabs value={projectTab} onValueChange={setProjectTab}><TabsList variant="line" className="line-tabs project-tabs"><TabsTrigger value="work">当前任务</TabsTrigger><TabsTrigger value="brief">任务要求</TabsTrigger><TabsTrigger value="messages">沟通记录</TabsTrigger><TabsTrigger value="history">进度记录</TabsTrigger></TabsList></Tabs><div className="project-content"><p className="tiny project-submitted">报名于 {new Date(p.submittedAt).toLocaleString('zh-CN')} · 约定 V{p.termsVersion}{p.confirmedTerms?' · 已确认 V'+p.confirmedTerms:''}</p>
 {projectTab==='brief'?<><h3>合作交付清单</h3><p className="body-copy">{c.deliverable}</p><ul className="check-list">{c.requirements.map(t=><li key={t}><Check size={16}/>{t}</li>)}</ul></>:projectTab==='messages'?chatView(p):projectTab==='history'?<div className="history-list">{p.history.map((h,i)=><div key={i}><span>{i+1}</span><div><strong>{h}</strong><p>项目事件记录</p></div></div>)}{p.versions.map(v=><div key={'v'+v.number}><span>V{v.number}</span><div><strong>{v.fileName||'文字初稿'}</strong><p>{v.at?new Date(v.at).toLocaleString('zh-CN'):''}</p><p>{v.draft||'已选择本地文件'}</p>{Object.entries(v.items||{}).map(([k,t])=><p key={k}>{k}：{t}</p>)}</div></div>)}</div>:<>
 {p.stage==='applied'&&<div className="application-status"><div className="application-status-heading"><span className="application-status-icon"><Clock3 size={25}/></span><div><h3>报名已提交</h3><p>品牌正在查看你的资料，收到反馈后会通知你。</p></div></div><div className="response-facts"><div><span>项目负责人</span><strong>Mia · 品牌合作团队</strong></div><div><span>预计反馈</span><strong>2 个工作日内</strong></div></div><div className="draft-preview application-note"><strong>我的合作说明</strong><p>{p.note||'暂未填写合作说明'}</p></div><div className="application-actions"><Action onClick={()=>setProjectTab('messages')}><MessageCircle size={16}/>联系项目负责人</Action><button className="text-btn withdraw-application" onClick={()=>move(p.id,'withdrawn')}>撤回报名</button></div><div className="simulation"><span><Play size={14}/>原型测试 · 品牌反馈</span><div><Action small secondary onClick={()=>move(p.id,'confirm')}>模拟入选</Action><Action small secondary onClick={()=>move(p.id,'rejected')}>模拟未入选</Action></div></div></div>}

 {p.stage==='confirm'&&<><h3>开始前，把约定说清楚 · V{p.termsVersion}</h3><p>{p.termsNote}</p><dl className="terms"><div><dt>合作报酬</dt><dd className="blue">USD {money(c.budget)}</dd></div><div><dt>交付内容</dt><dd>{c.deliverable}</dd></div><div><dt>初稿截止</dt><dd>{campaignDate(c,7)}</dd></div><div><dt>发布截止</dt><dd>{campaignDate(c,14)}</dd></div><div><dt>内容使用范围</dt><dd>品牌官方账号转载 30 天，非独家</dd></div><div><dt>支付条件</dt><dd>验收通过后 7 个工作日内结算</dd></div></dl><div className="action-row"><Action onClick={()=>{projectPatch(p.id,{confirmedTerms:p.termsVersion});move(p.id,'draft')}}>确认合作，开始创作 <ArrowRight size={17}/></Action><Action secondary onClick={()=>move(p.id,'negotiating')}>沟通调整</Action><Action secondary onClick={()=>move(p.id,'declined')}>拒绝合作</Action></div></>}
 {p.stage==='negotiating'&&<><h3>协商合作约定</h3><p>先在沟通记录说明需要调整的时间、报酬或交付内容。品牌提供新版约定后，你可以接受或拒绝。</p><Action secondary onClick={()=>setProjectTab('messages')}>打开沟通记录</Action><div className="simulation negotiation-controls"><Field label="新版约定"><Textarea aria-label="新版约定" value={p.termsNote} onChange={e=>projectPatch(p.id,{termsNote:e.target.value})}/></Field><Action disabled={!p.termsNote.trim()} onClick={()=>{projectPatch(p.id,{termsVersion:p.termsVersion+1});move(p.id,'confirm')}}>模拟品牌提交新版约定</Action></div><Action secondary onClick={()=>move(p.id,'declined')}>拒绝合作</Action></>}{['draft','revision'].includes(p.stage)&&<>{p.stage==='revision'&&<div className="feedback"><strong>品牌反馈 · 需要修改</strong><p>{p.feedback||'请查看沟通记录中的具体反馈。'}</p></div>}<h3>{p.stage==='revision'?'更新你的作品':'提交内容初稿'}</h3><p className="muted space-b">请按交付清单填写脚本或作品说明，准备好后提交给品牌审核。</p>{deliverables(c.id).map(item=><div className="delivery-item" key={item}><Field label={item}><Textarea aria-label={item} value={p.items[item]||''} onChange={e=>projectPatch(p.id,{items:{...p.items,[item]:e.target.value}})} placeholder="描述这一项的内容、创意或拍摄安排"/></Field><div className="attachment-row"><label className="attachment-picker"><UploadCloud size={18}/><span>选择本地附件</span><input type="file" aria-label={'选择文件 '+item} multiple accept="image/*,video/*,.pdf,.txt,.doc,.docx" onChange={e=>{const files=Array.from(e.target.files||[]);if(files.some(f=>f.size>200*1024*1024)){toast.error('单个演示文件不能超过 200 MB');return}if(files.length)projectPatch(p.id,{items:{...p.items,[item]:[p.items[item], '附件：'+files.map(f=>f.name).join('、')].filter(Boolean).join('\n')}})}}/></label><small>图片、视频或文档 · 单个文件不超过 200 MB</small></div></div>)}<Field label="创作总说明（选填）"><Textarea aria-label="创作总说明（选填）" value={currentDraft} onChange={e=>projectPatch(p.id,{draft:e.target.value})} rows={6} placeholder="写下你的创意、脚本或内容草稿…" maxLength={5000}/></Field><div className="action-row delivery-actions"><Action onClick={submitDraft}>{p.stage==='revision'?'提交修改版本':'提交审核'}<ArrowRight size={17}/></Action><Action secondary onClick={()=>toast.success('草稿已保存')}>保存草稿</Action><span className="tiny">提交版本 V{p.version+1}</span></div></>}
 {p.stage==='review'&&<div className="waiting"><FileText size={40}/><h3>V{p.version} 已提交审核</h3><p>{p.fileName||'文字初稿'}<br/>请等待反馈，暂时不需要发布。</p><div className="draft-preview">{Object.entries(p.items).map(([k,v])=><p key={k}><strong>{k}</strong><br/>{v}</p>)}{p.draft}</div><div className="simulation"><span><Play size={14}/>演示控制 · 模拟审核反馈</span><div><Action small secondary onClick={()=>{projectPatch(p.id,{feedback:'V'+p.version+' · Mia · '+new Date().toLocaleString('zh-CN')+'：请在 '+deliverables(c.id)[0]+' 中补充真实使用场景，并在重提交时说明修改内容。'});move(p.id,'revision')}}>要求修改</Action><Action small onClick={()=>move(p.id,'publish')}>审核通过</Action></div></div></div>}
 {p.stage==='publish'&&<><div className="success-note"><ShieldCheck size={20}/><div><strong>{p.returnReason?'发布链接需修正 ·':'内容已通过审核 ·'} V{Math.max(1,p.version)}</strong><p>{p.returnReason||'请使用已通过的版本发布，并在内容中注明品牌合作。'}</p></div></div><dl className="terms compact"><div><dt>发布平台</dt><dd>{c.platform}</dd></div><div><dt>发布时间</dt><dd>{campaignDate(c,8)} 至 {campaignDate(c,14)}</dd></div></dl><Field label="已发布内容链接"><Input type="url" aria-label="已发布内容链接" placeholder="https://…" value={linkValue||p.link} onChange={e=>{setLinkValue(e.target.value);projectPatch(p.id,{link:e.target.value})}}/></Field><p className="tiny space-b">请提供与约定平台一致的单条作品链接，并保持公开可访问。</p><Action onClick={()=>{try{const url=new URL(linkValue||p.link);if(!['http:','https:'].includes(url.protocol)||socialPlatform(url.href)!==c.platform)throw Error();projectPatch(p.id,{returnReason:undefined});move(p.id,'acceptance')}catch{toast.error('请输入与活动发布平台一致的有效公开链接')}}}>提交验收 <ArrowRight size={17}/></Action></>}
 {p.stage==='acceptance'&&<div className="waiting"><Link2 size={40}/><h3>发布链接已提交</h3><a className="url-text" href={p.link} target="_blank" rel="noreferrer">{p.link}</a><p>品牌将核对已发布内容与合作要求。</p><div className="simulation"><span><Play size={14}/>演示控制 · 模拟内容验收</span><div><Action small secondary onClick={()=>{projectPatch(p.id,{returnReason:'Mia：该链接未能定位到合作内容，请提供单条公开作品链接，并确认页面可访问。'});move(p.id,'publish')}}>链接需修正</Action><Action small onClick={()=>move(p.id,'settlement')}>验收通过</Action></div></div></div>}
 {['settlement','paid'].includes(p.stage)&&<><div className="settlement-amount"><span>本次合作报酬</span><strong><small>USD</small> {money(c.budget)}</strong><Status stage={p.stage}/></div><dl className="terms"><div><dt>合作金额</dt><dd>USD {money(c.budget)}</dd></div><div><dt>平台费用</dt><dd>USD 0</dd></div><div><dt>{p.stage==='paid'?'到账状态':'预计到账日期'}</dt><dd>{p.stage==='paid'?'已到账，可在钱包查看':expectedPayment(p.acceptedAt)}</dd></div></dl><p className="tiny">验收时间：{p.acceptedAt?new Date(p.acceptedAt).toLocaleString('zh-CN'):'待验收'}{p.paidAt?' · 到账时间：'+new Date(p.paidAt).toLocaleString('zh-CN'):''}</p><Action secondary onClick={()=>setProjectTab('messages')}>联系结算负责人</Action><Action onClick={()=>go('wallet')}>查看钱包 <Wallet size={17}/></Action>{p.stage==='settlement'&&<div className="simulation"><span><Play size={14}/>演示控制 · 不触发真实支付</span><Action small secondary onClick={()=>move(p.id,'paid')}>模拟报酬到账</Action></div>}</>}
 {closedStages.includes(p.stage)&&<Empty title="期待下一次，刚刚好的合作" description={p.feedback||stageInfo[p.stage].next}><Action onClick={()=>go('discover')}>继续发现活动 <ArrowUpRight size={17}/></Action></Empty>}
 </>}
 </div></section><aside><section className="surface project-aside"><h3>合作信息</h3><dl><dt>品牌</dt><dd>{c.brand}</dd><dt>发布平台</dt><dd>{c.platform}</dd><dt>合作报酬</dt><dd>USD {money(c.budget)}</dd><dt>交付要求</dt><dd>{c.deliverable}</dd></dl></section><section className="surface contact-card"><span className="contact-avatar">M</span><h3>Mia</h3><p>品牌项目负责人</p><Action secondary className="full" onClick={()=>setProjectTab('messages')}><MessageCircle size={16}/>联系负责人</Action></section></aside></div></>}
 function chatView(p:Project){return <><h3>与项目负责人沟通</h3><p className="tiny">在这里沟通创意、交付要求和项目进度。</p><div className="chat-messages">{p.messages.map((m,i)=><div className={'chat-message '+(m.who==='我'?'mine':'')} key={i}><small>{m.who}</small><p>{m.text}</p></div>)}</div><form className="chat-compose" onSubmit={e=>{e.preventDefault();if(!chatInput.trim())return;projectPatch(p.id,{messages:[...p.messages,{who:'我',text:chatInput.trim()}]});setChatInput('')}}><Input aria-label="项目留言" placeholder="关于这次合作，你想聊些什么？" value={chatInput} onChange={e=>setChatInput(e.target.value)} maxLength={1000}/><Action type="submit" disabled={!chatInput.trim()}><Send size={16}/>发送</Action></form></>}
 function walletView(){const records=[...state.withdrawals.map(w=>({id:w.id,title:'提现至 '+w.account.method,date:new Date(w.createdAt).toLocaleString('zh-CN'),amount:w.status==='failed'?0:-w.amount,status:w.status==='completed'?'已完成':w.status==='failed'?'失败，金额已退回':'处理中',type:'提现'})),...state.projects.filter(p=>['paid','settlement'].includes(p.stage)).map(p=>{const c=campaigns.find(c=>c.id===p.campaignId)!;return {id:p.id,title:c.brand+' · '+c.title,date:new Date(p.paidAt||p.acceptedAt||p.submittedAt).toLocaleString('zh-CN'),amount:c.budget,status:p.stage==='paid'?'已到账':'待结算',type:'合作收入'}})].filter(r=>walletFilter==='全部'||r.type===walletFilter);return <><div className="page-heading"><div><p className="eyebrow">MY WALLET</p><h1>每一份创作，都有回报<span className="blue">.</span></h1><p className="muted">收入、结算与提现，清清楚楚。</p></div><span className="tag">USD · 美元账户</span></div><div className="wallet-overview"><section className="balance-card"><div className="section-caption"><span>可提现余额</span><Wallet size={23}/></div><div className="balance-number"><small>USD</small>{Math.floor(available).toLocaleString('en-US')}<span>.{available.toFixed(2).split('.')[1]}</span></div><div className="balance-bottom"><p>最低提现 USD 50 · 处理中 USD {money(state.withdrawals.filter(w=>w.status==='processing').reduce((n,w)=>n+w.amount,0))}</p><button className="white-btn" disabled={available<50} onClick={startWithdraw}>申请提现 <ArrowUpRight size={17}/></button></div></section><section className="surface wallet-stat"><span>累计合作收入</span><strong><small>USD</small> {money(totalEarned)}</strong><p><CheckCircle2 size={14}/>已验收并到账</p></section><section className="surface wallet-stat"><span>待结算金额</span><strong><small>USD</small> {money(pending)}</strong><p><Clock3 size={14}/>待结算收入不可提现</p></section></div><div className="detail-layout wallet-layout"><section className="surface records-card"><div className="section-heading"><h2>收支记录</h2><Picker label="流水类型" value={walletFilter} onChange={setWalletFilter} options={['全部','合作收入','提现']}/></div><Table><TableHeader><TableRow><TableHead>项目 / 说明</TableHead><TableHead>金额</TableHead><TableHead>状态</TableHead><TableHead>操作</TableHead></TableRow></TableHeader><TableBody>{records.map(r=><TableRow key={r.id}><TableCell><strong>{r.title}</strong><small>{r.date}</small></TableCell><TableCell className={r.amount>0?'income':''}>{r.amount>0?'+':r.amount<0?'−':''} USD {money(Math.abs(r.amount))}</TableCell><TableCell><span className={'tag '+(r.status==='已到账'||r.status==='已完成'?'green':'amber')}>{r.status}</span></TableCell><TableCell><button className="text-btn" onClick={()=>r.type==='提现'?go('result',r.id):openProject(r.id)}>详情</button></TableCell></TableRow>)}</TableBody></Table>{tutorial===16&&<div className="tutorial-finish"><p>收入与提现记录已完整保留在本次练习中，结束后自动清除。</p><Action onClick={()=>finishTutorial(true)}>开始我的合作 <ArrowRight size={17}/></Action></div>}{!records.length&&<Empty title="暂时没有记录" description="完成合作或提交提现后，可在这里查看。"/>}</section><aside><section className="surface account-card"><div className="section-heading"><h3>收款账户</h3><CreditCard size={20}/></div>{state.accounts.length?state.accounts.map((a,i)=><div className="payment-account" key={i}><strong>{a.method}</strong><span>{a.name} · {a.address}<div className="action-row"><button className="text-btn" onClick={()=>{setNewAccount({...a});setEditingAccount(i);setAddingAccount(true);setDrawer('account')}}>编辑</button><button className="text-btn" onClick={()=>change(s=>({...s,accounts:s.accounts.filter((_,j)=>i!==j)}))}>移除</button></div></span></div>):<><div className="empty-icon"><CreditCard size={27}/></div><p className="muted centered">还没有添加收款账户</p></>}<Action secondary className="full" onClick={()=>{setAddingAccount(true);setEditingAccount(null);setNewAccount({method:'PayPal',region:'美国',name:'',address:''});setDrawer('account')}}><Plus size={16}/>添加收款账户</Action><p className="tiny centered">仅填写示例信息，无真实绑卡</p></section><div className="soft-note"><ShieldCheck size={18}/><div>申请提交不等于已到账。<br/>可随时查看每一笔处理进度。</div></div></aside></div></>}
 function resultView(){const w=state.withdrawals.find(w=>w.id===route.id);if(!w)return <Empty title="暂无提现结果" description="先到钱包提交一笔模拟提现。"><Action onClick={()=>go('wallet')}>前往钱包</Action></Empty>;const done=w.status==='completed',failed=w.status==='failed';return <div className="surface result-card"><div className={'result-icon '+(failed?'failed':'')}>{failed?<AlertCircle size={40}/>:done?<CheckCircle2 size={40}/>:<Clock3 size={40}/>}</div><span className="eyebrow">WITHDRAWAL {w.id}</span><h1>{failed?'提现未完成，请修正账户':done?'提现已完成':'提现申请已提交'}</h1><p className="muted">{failed?'示例原因：收款账户信息不匹配。金额已返回可提现余额。':done?'演示流程已完成，没有真实资金转移。':'当前正在处理中，实际到账以处理结果为准。'}</p><div className="result-facts"><div><span>提现金额</span><strong>USD {money(w.amount)}</strong></div><div><span>收款账户</span><strong>{w.account.method}</strong><small>{w.account.name} · {w.account.address}</small></div><div><span>提交时间</span><small>{new Date(w.createdAt).toLocaleString('zh-CN')}</small><span>当前状态</span><strong>{failed?'失败':done?'已完成':'处理中'}</strong></div></div>{failed?<div className="soft-note"><AlertCircle size={18}/>提现失败 · 金额已退回 · 等待你修正账户后重新申请</div>:<div className="project-progress result-progress">{['申请已提交','处理中','已完成'].map((t,i)=><div key={t} className={i===0||done?'complete':i===1?'current':''}><span>{i===0||done?<Check size={16}/>:i+1}</span><strong>{t}</strong>{i<2&&<i/>}</div>)}</div>}<div className="action-row centered">{failed&&<Action onClick={()=>{setNewAccount({...w.account});setEditingAccount(state.accounts.findIndex(a=>a.method===w.account.method&&a.address===w.account.address));setAmount(String(w.amount));setAccountIndex('');setAgreed(false);setAddingAccount(true);setDrawer('withdraw')}}>修改账户并重试</Action>}<Action secondary onClick={()=>go('wallet')}>查看钱包记录</Action><Action onClick={()=>go('discover')}>继续发现活动 <ArrowUpRight size={17}/></Action></div>{w.status==='processing'&&<div className="simulation"><span><Play size={14}/>演示控制</span><div><Action secondary small onClick={()=>change(s=>({...s,withdrawals:s.withdrawals.map(v=>v.id===w.id?{...v,status:'failed'}:v)}))}>模拟失败</Action><Action secondary small onClick={()=>change(s=>({...s,withdrawals:s.withdrawals.map(v=>v.id===w.id?{...v,status:'completed'}:v)}))}>模拟到账</Action></div></div>}</div>}
 function profileFields(){return <><div className="two-fields"><Field label="显示名称"><Input aria-label="显示名称" required maxLength={30} value={onboarding.name} onChange={e=>setOnboarding({...onboarding,name:e.target.value})}/></Field><Field label="邮箱"><Input aria-label="邮箱" required type="email" value={onboarding.email} onChange={e=>setOnboarding({...onboarding,email:e.target.value})}/></Field></div><div className="two-fields"><Field label="所在地区"><Picker label="所在地区" value={onboarding.region} onChange={v=>setOnboarding({...onboarding,region:v})} options={['中国','阿联酋','沙特阿拉伯','美国','其他']}/></Field><Field label="内容语言"><Picker label="内容语言" value={onboarding.language} onChange={v=>setOnboarding({...onboarding,language:v})} options={['中文','英文','阿拉伯语','中文 / 英文']}/></Field></div><Field label="内容方向"><Input aria-label="内容方向" required value={onboarding.topic} onChange={e=>setOnboarding({...onboarding,topic:e.target.value})} placeholder="例如：影像 / 科技 / 旅行"/></Field><Field label="社媒主页链接"><Input aria-label="社媒主页链接" required type="url" value={onboarding.social} onChange={e=>setOnboarding({...onboarding,social:e.target.value})} placeholder="https://…"/></Field></>}
 function onboardingView(){return <div className="onboarding-layout"><div className="onboarding-story"><p className="eyebrow">CREATE YOUR NEXT CHAPTER</p><h1>你的创作，<br/>值得更好的合作<span>.</span></h1><p>与欣赏你的品牌相遇。<br/>把热爱，变成持续的创作。</p><div className="join-brands"><span>DJI</span><span>Insta360</span><span>Anker</span></div><div className="join-note"><ShieldCheck size={17}/>先完善资料，再验证邮箱，开始发现活动。</div></div><section className="surface onboarding-form"><div className="onboarding-steps"><span className={route.view!=='verify'?'current':'complete'}><i>{route.view==='verify'?<Check size={14}/>:1}</i>基础资料</span><b/><span className={route.view==='verify'?'current':''}><i>2</i>邮箱验证</span></div>{route.view!=='verify'?<><h2>让合适的品牌找到你</h2><p className="muted space-b">只需填写匹配活动必要的信息。</p><form onSubmit={e=>{e.preventDefault();if(!onboarding.name.trim()||!onboarding.topic.trim()){toast.error('请填写完整资料');return}change(s=>updateProfile(s,onboarding));setOtp(tutorial!==null?'246810':'');setOtpError('');go('verify')}}>{profileFields()}<Action type="submit" className="full">验证邮箱并继续 <ArrowRight size={17}/></Action><p className="tiny centered">演示资料仅保存在此浏览器，不会发送到服务器。</p>{tutorial===null&&<Action secondary className="full" onClick={enterDemo}>以示例达人体验工作台</Action>}</form></>:<div className="verify-form"><div className="mail-icon"><Mail size={31}/></div><h2>验证你的邮箱</h2><p className="muted">验证邮箱：<strong>{onboarding.email}</strong></p><div className="demo-code">演示验证码 <strong>246810</strong><span>无需收取邮件</span></div><InputOTP maxLength={6} value={otp} onChange={setOtp} aria-label="邮箱验证码"><InputOTPGroup>{[0,1,2,3,4,5].map(i=><InputOTPSlot key={i} index={i}/>)}</InputOTPGroup></InputOTP>{otpError&&<p className="form-error" role="alert">{otpError}</p>}<Action className="full" onClick={()=>{if(otp!=='246810'){setOtpError('验证码不正确，请输入演示验证码 246810');return}change(s=>({...s,profile:onboarding,verified:true,verifiedEmail:onboarding.email.trim().toLowerCase()}));go('discover');toast.success('邮箱验证完成，欢迎加入 Airacle')}} disabled={otp.length<6}>验证并进入首页 <ArrowRight size={17}/></Action><div className="action-row centered"><button className="text-btn" disabled={resendCount>0} onClick={()=>{setResendCount(30);toast('演示验证码仍为 246810')}}>{resendCount?resendCount+' 秒后可重发':'重新发送'}</button><span className="muted">·</span>{tutorial===null&&<button className="text-btn" onClick={()=>go('onboarding')}>修改邮箱</button>}</div><div className="soft-note"><CheckCircle2 size={16}/>资料已保留，验证成功后直接进入首页。</div></div>}</section></div>}
 if(!ready)return <main className="workspace"><div className="surface empty-state" role="status">正在恢复你的工作台…</div></main>;
 const tourContext=route.view==='project'?'project:'+(projectTab==='work'?project?.stage:projectTab):route.view==='result'?'result:'+state.withdrawals.find(w=>w.id===route.id)?.status:route.view;
 const gated=!state.verified&&!['onboarding','verify'].includes(route.view);
 return <div className={(tutorial!==null?'tutorial-active ':'')+(previewControls?'preview-controls':'product-view')}>{renderHeader()}<main className={'workspace '+(['onboarding','verify'].includes(route.view)?'joining':'')}>{!drawer&&!dialog&&tutorialOverlay()}{gated?onboardingView():route.view==='discover'?discover():route.view==='detail'?(current?detail(current):<Empty title="活动不存在" description="返回首页查看所有活动。"><Action onClick={()=>go('discover')}>返回首页</Action></Empty>):route.view==='cooperations'?collaborations():route.view==='project'?(project&&pc?projectView(project,pc):<Empty title="还没有这个项目" description="报名后才能查看该合作。"><Action onClick={()=>go('cooperations')}>我的合作</Action></Empty>):route.view==='wallet'?walletView():route.view==='result'?resultView():onboardingView()}<footer className="footer"><span className="footer-logo">airacle</span><span>让好创作与好品牌相遇</span><button onClick={()=>setDialog('about')}>关于演示与图片来源</button></footer></main>
 <Dialog open={dialog!==null} onOpenChange={open=>{if(!open)setDialog(null)}}><DialogContent className="app-dialog" onEscapeKeyDown={e=>{if(document.querySelector('.spotlight-layer:popover-open'))e.preventDefault()}}><DialogHeader><DialogTitle>{dialog==='profile'?'你的创作档案':dialog==='certify'?'认证合作账号':'关于这个演示站'}</DialogTitle><DialogDescription>{dialog==='profile'?'完善匹配偏好，找到更合适的合作。':dialog==='certify'?'仅在活动要求时认证；完成后返回原活动继续报名。':'Airacle Creator Studio · 产品交互演示'}</DialogDescription></DialogHeader>{tutorialOverlay()}{dialog==='profile'?<form onSubmit={e=>{e.preventDefault();change(s=>updateProfile(s,onboarding));setDialog(null);if(onboarding.email.trim().toLowerCase()!==state.verifiedEmail){setOtp('');setOtpError('');go('verify');toast('邮箱已更改，请重新验证')}else toast.success('资料已更新，账号变更后需重新认证')}}>{profileFields()}<Action type="submit" className="full">保存资料</Action></form>:dialog==='certify'?certStatus==='done'?<div className="waiting"><CheckCircle2 className="green" size={42}/><h3>社媒账号已认证</h3><p>可以返回活动详情继续报名。</p><Action onClick={()=>setDialog(null)}>返回活动</Action></div>:certStatus==='pending'?<div className="waiting"><Clock3 size={42}/><h3>认证资料已提交</h3><p>人工审核中，报名内容已保留。<br/>审核通过后请手动返回活动提交报名。</p><div className="simulation"><span><Play size={14}/>演示控制</span><Action onClick={()=>{change(s=>({...updateProfile(s,{...s.profile,social:certUrl}),certifications:{[socialPlatform(certUrl)]:normalizeAccount(certUrl)}}));setCertStatus('done');toast.success('社媒认证已通过')}}>模拟认证通过</Action></div></div>:<><Field label="账号主页"><Input aria-label="认证账号主页" value={certUrl} onChange={e=>setCertUrl(e.target.value)}/></Field><label className="upload-zone small-upload"><UploadCloud size={28}/><strong>{certFile||'选择账号归属截图'}</strong><span>JPG / PNG · 最大 10 MB · 仅本地选择</span><input type="file" aria-label="选择认证截图" accept="image/jpeg,image/png" onChange={e=>{const f=e.target.files?.[0];if(f&&f.size<=10*1024*1024)setCertFile(f.name);else if(f)toast.error('请选择 10 MB 以下的截图')}}/></label><button className="text-btn" onClick={()=>setCertFile('演示账号归属截图.png')}>使用示例截图体验</button><div className="soft-note"><ShieldCheck size={18}/>优先采用截图人工认证，不展示暂不可用的第三方授权。</div><Action className="full" disabled={!certFile} onClick={()=>{try{const platform=socialPlatform(certUrl);if(!platform||(current&&platform!==current.platform))throw Error();setCertStatus('pending')}catch{toast.error('请填写有效的 '+(current?.platform||'YouTube、Instagram 或 X')+' 账号主页链接')}}}>提交认证</Action></>:<div className="about-content"><label className="preview-setting"><input type="checkbox" checked={previewControls} onChange={e=>setPreviewControls(e.target.checked)}/><span>显示原型测试工具<small>仅用于测试品牌反馈、审核与结算状态，默认关闭。</small></span></label><p>这是基于 13 个 UI 环节制作的独立演示站，所有订单、品牌合作、日期及金额为虚构示例，并非真实招募。</p><p>工作台演示数据保存在此浏览器；独立场景预览不影响工作台。不会发送邮件、上传文件、联系品牌或执行支付。</p><p>产品图片来自官方网页：</p><div className="source-links"><a href="https://www.dji.com/air-3/video" target="_blank" rel="noreferrer">DJI Air 3 <ExternalLink size={14}/></a><a href="https://store.insta360.com/" target="_blank" rel="noreferrer">Insta360 <ExternalLink size={14}/></a><a href="https://www.anker.com/eu-de/products/a1340-250w-power-bank" target="_blank" rel="noreferrer">Anker Prime <ExternalLink size={14}/></a></div></div>}</DialogContent></Dialog>
 <Sheet open={drawer!==null} onOpenChange={open=>{if(!open)setDrawer(null)}}><SheetContent className={tutorial!==null?"app-sheet tutorial-sheet":"app-sheet"} onEscapeKeyDown={e=>{if(document.querySelector('.spotlight-layer:popover-open'))e.preventDefault()}}><SheetHeader><SheetTitle>{drawer==='guide'?'体验完整合作链路':drawer==='notifications'?'消息与提醒':drawer==='account'?'收款账户管理':'提现与收款账户'}</SheetTitle><SheetDescription>{drawer==='guide'?'可按顺序体验，也可切换预设演示阶段。':drawer==='notifications'?'直接前往需要你处理的项目。':'演示模式，不会绑定真实账户或转移资金。'}</SheetDescription></SheetHeader><div className="sheet-body">{tutorialOverlay()}{drawer==='guide'?<><div className="guide-list">{guideLabels.map((label,i)=><button key={label} onClick={()=>jump(i)}><span>{String(i+1).padStart(2,'0')}</span><strong>{label}</strong><ChevronRight size={17}/></button>)}</div><p className="tiny">每个环节使用独立示例场景。退出预览即可恢复你的工作台，原订单和钱包不会被改写。</p></>:drawer==='notifications'?<>{state.projects.length?state.projects.flatMap(p=>p.history.map((event,index)=>({p,event,index}))).reverse().map(({p,event,index})=>{const c=campaigns.find(c=>c.id===p.campaignId)!;return <button className="notification-item" key={p.id+':'+index} onClick={()=>{change(s=>({...s,readNotifications:[...s.readNotifications,notificationId(p)]}));openProject(p.id)}}><div className="round-icon"><BriefcaseBusiness size={20}/></div><div><strong>{c.brand} · 项目动态</strong><p>{event}</p><small>{state.readNotifications.includes(notificationId(p))?'已读':'未读'} · 查看当前项目</small></div><ChevronRight size={16}/></button>}):<Empty title="暂时没有项目通知" description="报名后，项目反馈与到账事件会出现在这里。"/>}<div className="soft-note"><Bell size={17}/>打开项目通知后标为已读；这里保留历史动态，不会发送外部通知。</div></>:<>{drawer!=='account'&&<><div className="withdraw-balance"><span>可提现余额</span><strong>USD {money(available)}</strong><small>最低提现金额 USD 50</small></div><Field label="提现金额（USD）"><div className="amount-input"><Input aria-label="提现金额" type="number" min="50" max={available} step="0.01" value={amount} onChange={e=>{setAmount(e.target.value);setAgreed(false)}}/><button className="text-btn" onClick={()=>{setAmount(String(available));setAgreed(false)}}>全部</button></div></Field><div className="section-heading"><h3>收款账户</h3><button className="text-btn" onClick={()=>{setEditingAccount(null);setNewAccount({method:'PayPal',region:'美国',name:'',address:''});setAddingAccount(true)}}><Plus size={15}/>新增账户</button></div>{state.accounts.length>0&&<Select value={accountIndex} onValueChange={v=>{setAccountIndex(v);setAgreed(false)}}><SelectTrigger className="picker full" aria-label="收款账户"><SelectValue placeholder="选择收款账户"/></SelectTrigger><SelectContent>{state.accounts.map((a,i)=><SelectItem value={String(i)} key={i}>{a.method} · {a.name} · {a.address}</SelectItem>)}</SelectContent></Select>}</>}{addingAccount&&<form className="new-account" onSubmit={e=>{e.preventDefault();if(!newAccount.name.trim()||!newAccount.address.trim()){toast.error('请补全账户信息');return}try{const edit=editingAccount!==null&&editingAccount>=0?editingAccount:null;const index=edit??state.accounts.length;const next=saveAccount(stateRef.current,{...newAccount,address:newAccount.address.trim()},edit);change(()=>next);setAccountIndex(String(index));setAgreed(false);setAddingAccount(false);setEditingAccount(null);setNewAccount({method:'PayPal',region:'美国',name:'',address:''});if(drawer==='account')setDrawer(null);toast.success('账户已保存')}catch(e){toast.error((e as Error).message)}}}><h3>{editingAccount!==null&&editingAccount>=0?'编辑收款账户':'新增收款账户'}</h3><div className="two-fields"><Field label="收款方式"><Picker label="收款方式" value={newAccount.method} onChange={method=>setNewAccount({...newAccount,method,address:''})} options={['PayPal','Wise','银行转账']}/></Field><Field label="账户地区"><Picker label="账户地区" value={newAccount.region} onChange={region=>setNewAccount({...newAccount,region})} options={['美国','阿联酋','中国','其他']}/></Field></div><Field label="账户姓名"><Input aria-label="账户姓名" required value={newAccount.name} onChange={e=>setNewAccount({...newAccount,name:e.target.value})} placeholder="例如：Demo Creator"/></Field><Field label={newAccount.method==='银行转账'?'账户识别信息（演示）':'收款邮箱（演示）'}><Input aria-label="收款账户信息" required type={newAccount.method==='银行转账'?'text':'email'} value={newAccount.address} onChange={e=>setNewAccount({...newAccount,address:e.target.value})} placeholder={newAccount.method==='银行转账'?'仅填写示例编号 6789':'demo@example.com'}/></Field><Action type="submit" className="full" secondary>保存并选中</Action></form>}{drawer!=='account'&&<><p className="form-error">{moneyError(amount,available)}</p><div className="soft-note">演示费用 USD 0 · 预计 1–3 个工作日到账。实际服务未接入。</div><div className="checkbox-line"><Checkbox id="withdraw-agree" checked={agreed} onCheckedChange={v=>setAgreed(v===true)}/><Label htmlFor="withdraw-agree">我已确认本次模拟提现金额与收款账户信息。</Label></div>{withdrawError&&<p role="alert" className="form-error">{withdrawError}</p>}{accountIndex!==''&&state.accounts[Number(accountIndex)]&&<div className="soft-note">确认收款人：{state.accounts[Number(accountIndex)].name} · {state.accounts[Number(accountIndex)].method} · {state.accounts[Number(accountIndex)].address}<br/>预计到账净额：USD {money(Number(amount)||0)}</div>}<Action className="full" disabled={!agreed||!accountIndex||!state.accounts[Number(accountIndex)]||!Number.isFinite(Number(amount))||Number(amount)<50||Number(amount)>available||Math.abs(Number(amount)*100-Math.round(Number(amount)*100))>0.000001} onClick={()=>{try{const next=withdraw(stateRef.current,Number(amount),state.accounts[Number(accountIndex)]);change(()=>next);go('result',next.withdrawals[0].id);toast.success('模拟提现申请已提交')}catch(e){setWithdrawError((e as Error).message)}}}>确认模拟提现 <ArrowRight size={17}/></Action><p className="tiny centered">{available<50?'当前余额不足 USD 50，暂不可提现。':'提交后余额将扣除对应金额，失败后会退回。'}</p></>}</>}</div></SheetContent></Sheet>
 <Toaster position="bottom-center" richColors closeButton/>
 </div>;
}
